const rotateAngle = 45;

export const moveShadow = (angle: number) => {
  angle = ((angle % 360) + 360) % 360;
  const coordinates = { x: 0, y: 0 };

  const direction = Math.floor(angle / rotateAngle);
  console.log("🚀", angle, direction, angle % rotateAngle);
  debugger;
  console.log(
    "percent",
    rotateAngle * direction,
    rotateAngle * (direction + 1),
  );

  switch (direction) {
    case 0:
    case 1:
    case 7:
      // coordinates.x = getPercent(
      //   rotateAngle * direction,
      //   rotateAngle * direction + 1,
      //   angle,
      // );
      break;

    default:
      break;
  }

  // Визначаємо напрямок за кутом
  if ((angle >= 0 && angle < 45) || (angle >= 315 && angle <= 360)) {
    return { x: 1, y: 0 }; // Рух вправо
  } else if (angle >= 45 && angle < 135) {
    return { x: 1, y: 1 }; // Рух вниз і вправо
  } else if (angle >= 135 && angle < 225) {
    return { x: 0, y: 1 }; // Рух вниз
  } else if (angle >= 225 && angle < 315) {
    return { x: -1, y: 1 }; // Рух вниз і вліво
  } else {
    return { x: 0, y: 0 }; // Немає руху
  }
};
